from sqlglot import exp
from sqlglot.executor.table import ensure_tables, Table
for d, dialect in [
    ({'People': [{'ID': 1, 'Name': 'Alice'}, {'ID': 2, 'Name': 'Bob'}]}, None),
    ({'empty': []}, None),
    ({'Db': {'People': [{'ID': 1}]}}, None),
    ({'catalog': {'db': {'people': [{'id': 1}]}}}, None),
    ({'a b': [{'c d': 2}]}, None),
    ({'Foo': [{'Bar': 1}]}, 'snowflake'),
]:
    try:
        tables=ensure_tables(d,dialect=dialect)
        print('\ninput',d,'dialect',dialect)
        print('mapping', tables.mapping)
        print('args',tables.supported_table_args)
        for name in ['people','People','db.people','catalog.db.people','a b','foo']:
            tbl=exp.to_table(name)
            try:
                print(name, '=>', tables.find(tbl, raise_on_missing=False))
            except Exception as e: print(name,'ERR',type(e).__name__,e)
    except Exception as e: print('ERR overall',type(e).__name__,e)
PY"}

