from sqlglot import parse_one
from sqlglot.executor import execute
from sqlglot.errors import ExecuteError, ParseError, OptimizeError

cases = [
 ('no tables', "SELECT 1 AS one, 'x' AS s, 2 + 3 AS n", {}),
 ('empty table', 'SELECT * FROM t', {'t': []}),
 ('empty agg', 'SELECT COUNT(*) AS n FROM t', {'t': []}),
 ('column aliases', 'SELECT id AS i, name n FROM t ORDER BY i', {'t':[{'id':2,'name':'b'},{'id':1,'name':'a'}]}),
 ('null sort first', 'SELECT x FROM t ORDER BY x NULLS FIRST', {'t':[{'x':2},{'x':None},{'x':1}]}),
 ('null sort last', 'SELECT x FROM t ORDER BY x NULLS LAST', {'t':[{'x':2},{'x':None},{'x':1}]}),
 ('desc', 'SELECT x FROM t ORDER BY x DESC', {'t':[{'x':2},{'x':None},{'x':1}]}),
 ('string', "SELECT name FROM t WHERE name LIKE 'a%' ORDER BY name", {'t':[{'name':'alice'},{'name':'bob'},{'name':'anna'}]}),
 ('in list', 'SELECT x FROM t WHERE x IN (1, 3, NULL) ORDER BY x', {'t':[{'x':1},{'x':2},{'x':3}]}),
 ('not in', 'SELECT x FROM t WHERE x NOT IN (1, NULL) ORDER BY x', {'t':[{'x':1},{'x':2}]}),
 ('between', 'SELECT x FROM t WHERE x BETWEEN 2 AND 4 ORDER BY x', {'t':[{'x':1},{'x':2},{'x':4},{'x':5}]}),
 ('arithmetic', 'SELECT 7 / 2 AS div, 7 % 2 AS mod, 2 ^ 3 AS pow', {}),
 ('bool', 'SELECT TRUE AS t, FALSE AS f, NULL IS NULL AS n', {}),
 ('cast bool', "SELECT CAST('' AS BOOLEAN) AS b", {}),
 ('quoted', 'SELECT "name" FROM "t"', {'t':[{'name':'x'}]}),
 ('aliased', 'SELECT p.name FROM people AS p ORDER BY p.name', {'people':[{'name':'z'},{'name':'a'}]}),
]
for label, sql, tables in cases:
    try:
        r=execute(sql,tables=tables)
        print(label,'OK',r.columns,r.rows)
    except Exception as e: print(label,'ERR',type(e).__name__,e)
# expression input
try: print('expr', execute(parse_one('SELECT 1 AS x')).rows)
except Exception as e: print('expr err',type(e).__name__,e)
# dialect input and table names
try: print('dialect', execute('SELECT * FROM people', dialect='snowflake', tables={'PEOPLE':[{'A':1}]}).columns)
except Exception as e: print('dialect err',type(e).__name__,e)
# parse error
